# Johnson 法则
for 每个作业: 记 (a, b, id)
sort 作业 by min(a,b)
A = []  # 收集 a < b 的作业 (放前面)
B = []  # 收集 a >= b 的作业 (放后面)
for job in sorted:
    if job.a < job.b: A.append(job)
    else: B.append(job)
order = A + reversed(B)   # B 部分反转
# 计算完工时间:
t1 = t2 = 0
for job in order:
    t1 += job.a
    t2 = max(t2, t1) + job.b
makespan = t2
